    "text": "한 아이가 물었다, 풀이 뭐예요? 두 손 가득 풀을 뜯어와 나에게 건네며. 내가 어떻게 그 아이에게 답할 수 있었을까? 나도 그 아이만큼이나 그것이 무엇인지 모르는데. 짐작건대 그것은 희망에 찬 초록빛 재료로 짜인, 내 기질의 깃발인가 보다.",
