    "id": "l11",
    "text": "사느냐 죽느냐, 이것이 문제로다.\n\n가혹한 운명의 화살과 돌팔매를 맞으며 참는 것이 더 고귀한 일인가, 아니면 고난의 바다에 맞서 싸워 끝장을 내는 것이 더 고귀한 일인가. 죽는다는 것, 잠드는 것, 그뿐이다. 잠듦으로써 마음의 고통과 육신이 물려받은 수천 가지 자연의 충격을 끝낼 수 있다면, 그것은 간절히 바랄 만한 종결이 아닌가.",
