    "id": "l44",
    "text": "이 노란 노예는 종교를 만들고 부수며, 저주받은 자를 축복하고, 문둥이를 사랑받게 하며, 도둑에게 지위와 무릎 꿇는 예우와 원로원의 칭송을 안겨준다.\n\n이것은 늙은 과부를 다시 신부로 만드는 것이다. 병원의 상처와 종기조차도 향기롭게 만드는 것이 바로 이것, 저주받은 흙이며, 인류 공통의 창녀다.",
