    "text": "갈대밭에서 잘려 나온 이래로, 이 갈대 피리는 그 신음으로 울고 있다.\n\n나를 뿌리에서 잘라낸 그 이별 때문에, 남자든 여자든 나의 울음에 함께 운다. 이별로 찢긴 가슴을 나는 가지고 있으니, 그리움의 고통을 설명하기 위해서이다.\n\n제 근원에서 멀어진 자는 누구나, 다시 그 합일의 때를 그리워한다.",
