    "text": "재산 좀 있는 독신 남자라면 반드시 아내가 필요하리라는 것은 세상이 다 인정하는 진리이다.\n\n이런 남자가 어느 동네로 이사를 오게 되면, 주위의 가족들은 그의 감정이나 생각은 전혀 모르면서도 그를 자기 딸 가운데 누군가의 정당한 소유물로 여기게 된다.",
