    "cat": "문학",
    "bm": false,
    "note": "러시아 대문호 도스토예프스키의 소설. 세상에서 물러나 지하 같은 골방에 틀어박힌 한 인간의 뒤틀린 독백으로 시작한다.",
    "bookTitle": "지하로부터의 수기",
