    "cat": "문학",
    "bm": false,
    "note": "\"아름다움이 세상을 구원한다\"는 이 문장은 흔히 도스토예프스키의 확신에 찬 선언처럼 인용되지만, 정작 소설 속에서는 다른 인물이 반신반의하며 되묻는 질문으로 나온다.",
    "bookTitle": "백치",
