    "note": "소설의 마지막 문단이다. 주인공 도로시아는 성녀가 되고 싶었지만 평범한 아내로 생을 마친다. 엘리엇은 그것을 실패로 그리지 않는다. 역사에 남는 삶만이 의미 있다는 통념 자체가 이 소설이 겨냥하는 표적이다.",
