    "id": "l64",
    "text": "\"바틀비.\" 나는 말했다. \"지금 당장 이리 오게.\"\n\n대답이 없었다.\n\n\"바틀비.\" 나는 조금 더 큰 소리로 말했다.\n\n대답이 없었다.\n\n\"바틀비!\" 나는 고함쳤다.\n\n유령처럼, 그가 칸막이 문간에 나타났다.\n\n\"옆방으로 가서 터키에게 이리 오라고 전하게.\"\n\n\"그렇게 하지 않는 편을 택하겠습니다.\" 그는 부드럽고 조용하게 말하고는 조용히 사라졌다.\n\n나는 한동안 소금 기둥처럼 서 있었다.",
    "author": "허먼 멜빌",
    "source": "필경사 바틀비, 1853",
    "cat": "문학",
    "bm": false,
    "note": "월가의 법률사무소를 배경으로 한 단편이다. 필경사 바틀비는 어느 날부터 일을 하지 않기 시작하지만, 이유를 대지도 다른 요구를 하지도 않는다. 반항이나 요구였다면 벌하거나 협상할 수 있었을 텐데, 바틀비의 대답은 그 어느 쪽도 아니어서 고용주는 그를 어떻게 다뤄야 할지조차 알 수 없다. 이 말 한마디는 이후 명령과 순응의 언어 바깥에서 저항이 가능한지를 묻는 자리로 계속 인용되었다.",
    "bookTitle": "필경사 바틀비",
