    "id": "l67",
    "text": "지금도 나는 여전히 이상들을 붙들고 있다. 이 모든 것에도 불구하고, 그럼에도 나는 여전히 믿는다. 사람들은 마음속 깊은 곳에서 정말로 선하다고.\n\n나는 도저히 내 희망을 혼란과 비참과 죽음의 토대 위에 세울 수가 없다. 세상이 서서히 황무지로 변해 가는 것이 보이고, 우리마저 짓밟아 버릴 천둥소리가 점점 가까워지는 것이 들린다. 수백만의 고통이 느껴진다.\n\n그런데도 하늘을 올려다보면, 어쩐지 모든 것이 다시 좋아지리라는 생각이 든다. 이 잔혹함마저 끝날 것이고, 평화와 고요가 다시 돌아오리라는 생각이 든다.",
    "author": "안네 프랑크",
    "source": "안네의 일기, 1944년 7월 15일",
    "cat": "문학",
    "bm": false,
