    "id": "l68",
    "text": "인간에게는, 자유롭게 태어난 존재가 자신의 자유를 서둘러 넘겨줄 대상을 찾는 것보다 더 절박하고 더 괴로운 근심거리가 없다. 그러나 인간의 자유를 넘겨받으려는 자는, 그의 양심을 잠재울 수 있는 자여야 한다.\n\n너는 인간에게서 굴복의 확실성마저 빼앗고, 자유로운 사랑을 요구했다. 옛 율법 대신 인간은 이제 스스로 무엇이 선이고 무엇이 악인지를, 오직 네 형상을 길잡이 삼아 자유로운 마음으로 결정해야 한다.\n\n그러나 그토록 무서운 짐에 짓눌린 인간이 마침내 네 형상과 네 진리마저 물리치게 되리라는 것을, 너는 정말 생각지 못했느냐?",
    "author": "표도르 도스토예프스키",
