    "id": "l71",
    "text": "2 곱하기 2는 4다. 그러나 감히 말하건대, 2 곱하기 2는 5인 것도 때로는 아주 사랑스러운 일이다.\n\n인간은 창조하고 길을 닦기를 좋아한다. 그것은 분명하다. 그러나 어째서 인간은 파괴와 혼돈도 그토록 열정적으로 좋아하는가? 어쩌면 인간은 목표에 도달하는 것이 아니라 그것을 향해 나아가는 과정만을 좋아하는지도 모른다.\n\n인간이 그토록 목표를 사랑한다면, 어째서 완성된 것 앞에서 두려워하는가?",
