    "id": "l73",
    "text": "어느 날 아침 그레고르 잠자가 불안한 꿈에서 깨어났을 때, 그는 자신이 침대 위에서 한 마리 거대한 벌레로 변해 있는 것을 발견했다.\n\n\"아, 하느님.\" 그는 생각했다. \"내가 어쩌다 이렇게 고된 직업을 택했을까. 기차 시간 걱정, 형편없는 식사, 결코 진심이 될 수 없는 사람들과의 만남. 이 모든 것이 악마에게나 가 버려라!\"\n\n그는 배 위쪽이 가려운 것을 느꼈다. 몸을 밀어 고개를 들어 보니, 가려운 곳은 하얀 작은 점들로 덮여 있었다. 다리로 건드려 보려는 순간 온몸에 오한이 훑고 지나가, 곧 다리를 거두었다.",
