    "id": "l89",
    "text": "그는 무엇을 해야 할지, 무엇을 생각해야 할지 알 수 없었다. 마침내 책상으로 가서 사랑했던 여인에게 편지를 썼다. 용서를 구하며 스스로를 미쳤다고 탓하는 편지였다. 그는 슬픔의 거친 말들로, 그보다 더 거친 고통의 말들로 페이지를 채워 나갔다.\n\n자책에는 은밀한 사치가 있다. 스스로를 탓할 때 우리는 다른 누구도 우리를 탓할 권리가 없다고 느낀다. 우리에게 사함을 주는 것은 신부가 아니라 고백 그 자체다.\n\n도리언은 편지를 다 쓰고 나자, 이미 용서받았다고 느꼈다.",
