    "id": "l90",
    "text": "우리는 신이 아니야. 내가 심각한 고통 속에 있다고 해도, 다른 사람은 내가 어떤 고통을 겪고 있는지 결코 알 수 없어. 그는 나와 다른 사람이니까.\n\n그런데 진짜 문제는 사람들은 타인의 고통을 인정하기 싫어한다는 거야. 마치 그걸 인정하는 순간 자기가 뭔가를 잃기라도 하는 것처럼. 왜 그런 것 같아?",
