    "text": "개츠비는 초록 불빛을 믿었다. 해마다 우리 앞에서 멀어져 가는, 환희에 찬 미래를. 그때는 우리를 벗어났지만 상관없다 — 내일 우리는 더 빨리 달릴 것이고, 두 팔을 더 멀리 뻗을 것이다… 그리고 어느 맑은 아침에는——\n\n그리하여 우리는 물살을 거스르는 배처럼, 끊임없이 과거로 떠밀리면서도 계속 앞으로 나아가는 것이다.",
