    "id": "l99",
    "text": "윈스턴은 자리에서 꼼짝도 하지 않았지만, 마음속에서 그는 바깥의 군중 속에 섞여 귀가 먹도록 환호하고 있었다. 웨이터 하나가 진 병을 들고 다가왔지만, 행복한 꿈에 잠긴 그는 잔이 채워지는 것도 알아채지 못했다.\n\n그는 그 거대한 얼굴을 올려다보았다. 검은 콧수염 아래 감춰진 미소가 어떤 것인지 알아내는 데 사십 년이 걸렸다. 아, 잔인하고 부질없는 오해여. 아, 사랑의 품에서 고집스레 제 발로 걸어 나간 유배자여. 진 냄새가 나는 눈물 두 줄기가 그의 코 양옆을 타고 흘러내렸다. 그러나 괜찮았다, 모든 것이 괜찮았다, 투쟁은 끝났다. 그는 자기 자신과의 싸움에서 승리했다. 그는 빅 브라더를 사랑했다.",
