    "id": "l100",
    "text": "그때 처음으로 그는 분명히 깨달았다. 자신이 그녀와 가깝다는 사실뿐 아니라, 이제 어디서부터가 자신이고 어디까지가 그녀인지 알 수 없게 되었다는 것을. 그 순간 그가 느낀 것은 둘로 갈라지는 듯한 고통스러운 감각이었다.\n\n처음에는 화가 났다. 그러나 바로 다음 순간, 그는 그녀에게 화를 낼 수 없다는 것을 느꼈다 — 그녀가 곧 자기 자신이었으므로.",
