    "id": "l102",
    "text": "\"인류를 사랑하긴 합니다.\" 그는 말했습니다. \"하지만 스스로에게 놀라곤 하지요. 인류 전체를 더 많이 사랑하면 할수록, 개별적인 사람들, 즉 사람들 개개인은 점점 덜 사랑하게 된다는 것을요. 꿈속에서는 인류를 위해 십자가에 못 박힐 수도 있다고 믿었건만, 정작 저는 단 이틀도 누군가와 한방에서 지내지 못합니다. 누군가 제 곁에 있는 순간, 그의 존재가 제 자유를 옥죄어 오거든요. 하루 만에 저는 가장 훌륭한 사람조차 미워하게 될 수 있습니다. 그런데 반대로, 개별적인 사람들을 미워하면 미워할수록 인류 전체에 대한 제 사랑은 오히려 더 뜨거워지곤 했습니다.\"",
