    "id": "l103",
    "text": "자유와 만인을 위한 충분한 빵은 결코 함께할 수 없다. 사람들은 결코, 결코 그 둘을 나눠 가질 수 없을 것이기 때문이다.\n\n인간 존재의 비밀은 그저 사는 것이 아니라 무엇을 위해 살 것인가에 있으니까. 자신이 무엇을 위해서 사는가에 대한 확고한 관념이 없다면 인간은, 설령 그의 주위가 온통 빵 천지라 할지라도, 사는 것에 동의하지 않을 것이며 지상에 남느니 차라리 스스로를 박멸할 것이다.",
    "author": "표도르 도스토예프스키",
    "source": "카라마조프가의 형제들, 5권 5장 대심문관",
    "cat": "문학",
    "bm": false,
    "note": "대심문관이 그리스도에게 하는 말이다. 자유가 있으면 사람들은 저마다 다르게 살고 다르게 가지며, 그 차이는 결국 누군가가 굶는 결과로 이어진다. 모두에게 빵을 보장하려면 자유를 거두어야 한다.",
    "bookTitle": "카라마조프가의 형제들",
