    "id": "l104",
    "text": "\"아니, 살아라\"라는 말을 듣지. 내가 없으면 아무것도 없을 테니까. 만약 우주의 모든 것이 이치에 맞다면, 아무 일도 일어나지 않을 거야. 나 없이는 사건이 없고, 사건은 있어야만 하거든. 그래서 나는 마지못해 사건을 만들어 내는 일을, 명령받은 대로 비이성적인 일을 하고 있는 거지.\n\n그 확고한 지성에도 불구하고, 인간들은 이 소극(笑劇)을 진지한 것으로 받아들여. 그게 그들의 비극이지. 물론 그들은 고통받아… 하지만 그들은 산다, 진짜로 산다, 환상 속이 아니라. 왜냐하면 고통이란 것이 곧 삶이기도 하니까. 고통이 없다면 인생에 무슨 낙이 있겠나 — 모든 것이 끝없는 기도의 연속으로 바뀔 텐데.",
    "author": "표도르 도스토예프스키",
    "source": "카라마조프가의 형제들, 11권 9장 악마, 이반의 악몽",
    "cat": "문학",
    "bm": false,
    "note": "이반의 환각 속에 나타난 악마가 하는 말이다. 그는 스스로를 세상에 불합리와 사건을 일으키도록 명령받은 존재라 자조한다. 모든 것이 이치대로만 흘러간다면 아무 일도 일어나지 않을 것이므로, 자신 같은 존재가 필요하다는 것이다. 스메르자코프가 목을 맨 사실을 알료샤가 전하러 오기 직전, 이반이 열병 속에서 겪는 대화다.",
    "bookTitle": "카라마조프가의 형제들",
