    "id": "l105",
    "text": "돈만 있으면 말이죠 — 저는 최고로 독창적인 인간이 될 겁니다. 돈보다 치사하고 증오스러운 게 없다는 말은, 그것이 인간에게 재능까지 부여하기 때문이지요. 그리고 그것은 세상이 끝날 때까지 그럴 겁니다.",
