    "id": "l107",
    "text": "나는 이 여자를 사랑한다. 어찌해야 할지 모를 만큼 사랑한다. 그것이 내 고뇌의 시작이다. 하지만 이제 됐다. 나는 사랑하면서도 멀어질 수 있는 어떤 힘을 얻었다. 살아가기 위해서는 사랑조차 희생해야 한다. 뭐야, 당연한 일이잖아. 세상 사람들은 다들 그렇게 살아가고 있다.",
