    "id": "e21",
    "text": "역은 궁하면 변하고, 변하면 통하고, 통하면 오래간다.\n\n천지의 도는 쉬지 않고 변한다. 해가 가면 달이 오고, 달이 가면 해가 온다. 추우면 더워지고, 더우면 추워진다. 가고 오는 것이 서로 감응하여 변화가 생겨난다.",
    "author": "작자 미상",
    "source": "주역, 계사전 하편 2장",
    "cat": "동양고전",
    "bm": false,
    "note": "'궁즉통(窮則通)'이라는 말이 여기서 나왔다. 계사전은 주역 본문에 붙은 해설로, 점치는 책이었던 주역을 철학 텍스트로 읽는 길을 열었다.",
    "bookTitle": "주역",
    "isbn": "",
    "publisher": "",
    "translator": "",
    "kyoboLink": "https://bitl.bz/api@8fqFNa6N",
