    "note": "'하늘의 그물은 넓고 넓어 성기지만 빠뜨리지 않는다'는 '천망회회 소이불실(天網恢恢 疏而不失)'로, 이 장에서 나온 널리 쓰이는 성어다.",
    "bookTitle": "도덕경",
