    "cat": "동양고전",
    "bm": false,
    "note": "'대기만성(大器晩成)'이 여기서 나왔다. 다만 이 장의 문맥에서는 '큰 인물은 늦게 완성된다'는 격려의 뜻보다, 큰 것일수록 감각으로 붙잡히지 않는다는 역설을 말하는 대목이다.",
