    "id": "e34",
    "text": "사람은 누구나 남의 불행을 차마 보지 못하는 마음이 있다.\n\n지금 어떤 사람이 갑자기 어린아이가 우물에 빠지려는 것을 보았다고 하자. 누구나 깜짝 놀라 측은해하는 마음이 든다. 그것은 그 아이의 부모와 친분을 맺기 위해서가 아니고, 마을 사람들과 벗들에게 칭찬을 듣기 위해서도 아니며, 아이의 울부짖는 소리가 싫어서도 아니다.\n\n이로 미루어 보면, 측은해하는 마음이 없으면 사람이 아니다.",
    "author": "맹자",
    "source": "맹자, 공손추 상편 6장",
    "cat": "동양고전",
    "bm": false,
    "note": "맹자가 성선설을 논증하는 대목이다. 그는 사람이 착하다고 주장하는 대신, 하나의 상황을 상상해 보라고 한다. 아이가 우물에 빠지려는 순간에 계산이 끼어들 틈이 있느냐는 것이다.",
    "bookTitle": "맹자",
