    "note": "'호연지기(浩然之氣)'라는 말이 여기서 나왔다. 맹자는 이 기운이 의로운 행동을 쌓아야 자라는 것이지, 한 번의 의로운 행동으로 갑자기 얻어지는 것이 아니라고 못 박는다.",
