    "note": "'오십보백보'의 출전이다. 양혜왕은 흉년에 백성을 옮겨 주는 등 구휼책을 폈다고 자부했는데, 맹자는 그것이 이웃 나라와 정도의 차이일 뿐이라고 답한 것이다.",
