    "note": "흔히 '백전백승'으로 알려져 있으나, 원문은 '백 번 싸워도 위태롭지 않다(百戰不殆)'이다. 손자가 겨눈 것은 이기는 것이 아니라 위태로워지지 않는 것이었고, 그래서 싸우지 않고 적을 굴복시키는 것을 최선으로 꼽았다.",
    "bookTitle": "손자병법",
