    "cat": "동양고전",
    "bm": false,
    "note": "'우공이산(愚公移山)'이라는 말이 여기서 나왔다. '우공(愚公)'은 어리석은 노인, 그를 비웃은 '지수(智叟)'는 지혜로운 늙은이라는 뜻으로, 이름 자체가 뒤집힌 대비를 이룬다.",
    "bookTitle": "열자",
