    "id": "e38",
    "text": "앎과 행함은 하나다. 앎이면서 행하지 않는 자는 아직 알지 못한 것이다. 성현이 사람에게 알고 행하라고 가르친 것은, 원래 하나인 본체를 회복시키려 한 것이지, 둘로 나누어 그렇게 하라는 것이 아니다.\n\n좋은 색을 보는 것은 앎에 속하고 좋은 색을 좋아하는 것은 행함에 속하는데, 좋은 색을 보는 순간 이미 좋아하는 것이지, 본 뒤에 다시 마음을 세워 좋아하는 것이 아니다.",
