    "id": "e42",
    "text": "변방에 사는 늙은이의 말이 호 땅으로 달아났다. 사람들이 위로하자 노인이 말했다. 이것이 어찌 복이 되지 않겠는가.\n\n몇 달 뒤 그 말이 호의 준마를 데리고 돌아왔다. 사람들이 축하하자 노인이 말했다. 이것이 어찌 화가 되지 않겠는가. 집에 좋은 말이 많아지자 아들이 타다가 떨어져 다리가 부러졌다. 사람들이 위로하자 노인이 말했다. 이것이 어찌 복이 되지 않겠는가.\n\n일 년 뒤 호인이 쳐들어왔다. 장정들이 전쟁에 나가 열에 아홉이 죽었으나, 이 아들은 다리가 불편하여 부자가 함께 살아남았다.",
