    "id": "e46",
    "text": "왕자유가 눈 내리는 밤에 잠에서 깨어 문을 열고 술을 마시며 사방을 둘러보았다. 온 천지가 희고 고요했다. 홀연히 멀리 사는 벗 대규가 생각났다.\n\n즉시 작은 배를 타고 밤새 그를 찾아갔다. 그러나 그 집 문 앞에 이르러서는 돌아왔다.\n\n사람들이 까닭을 묻자 말했다. 본래 흥이 일어 갔는데, 흥이 다하여 돌아온 것이다. 어찌 반드시 대규를 만나야 하겠는가.",
