    "id": "e26",
    "text": "사람이 이 세상에 태어나 학문을 하지 않으면 사람이라 할 수 없다. 이른바 학문이란 다른 것이 아니라, 일상의 인륜에서 마땅히 행할 바를 행하는 것이다.\n\n먼저 뜻을 세워야 한다. 성현이 되겠다는 뜻을 세우지 않으면 어찌 성현에 이를 수 있겠는가. 뜻을 세운 뒤에는 게을러서는 안 된다.",
