    "id": "e19",
    "text": "하늘이 명한 것을 성이라 하고, 성을 따르는 것을 도라 하며, 도를 닦는 것을 교라 한다.\n\n도란 잠시도 떠날 수 없는 것이니, 떠날 수 있으면 도가 아니다. 그러므로 군자는 보이지 않는 곳에서도 삼가고, 들리지 않는 곳에서도 두려워한다.",
