    "id": "e4",
    "text": "북해에 물고기가 있으니 이름이 곤이다. 곤의 크기는 몇천 리인지 알 수 없다. 변하여 새가 되니 이름이 붕이다. 붕의 등도 몇천 리인지 알 수 없다.\n\n분연히 날아오르면 그 날개가 하늘에 드리운 구름과 같다. 이 새는 바다가 움직일 때 남쪽 바다로 옮겨 가려 한다. 남쪽 바다란 곧 하늘 못이다.",
