    "source": "장자, 지락편",
    "cat": "동양고전",
    "bm": false,
    "note": "혜자는 장자의 오랜 벗이자 논쟁 상대다. 아내가 죽었는데 장자가 질그릇을 두드리며 노래하자 혜자가 나무라는데, 이어지는 대화에서 장자는 삶과 죽음을 사계절의 순환처럼 받아들인다고 답한다.",
