    "id": "e17",
    "text": "나비인지 내가 나비의 꿈을 꾸고 있는 것인지, 내가 나비인지 나비가 나의 꿈을 꾸고 있는 것인지, 알 수가 없다.\n\n장주가 꿈에 나비가 되었다. 훨훨 날아다니는 나비였다. 스스로 즐거워 마음대로 날아다녔는데, 자기가 장주인 줄 몰랐다. 문득 깨어나니 엄연히 장주였다.\n\n장주가 꿈에 나비가 된 것인가, 나비가 꿈에 장주가 된 것인가.",
