    "id": "e41",
    "text": "장자와 혜자가 호수의 다리 위를 거닐고 있었다. 장자가 말했다. 피라미가 유유히 헤엄치고 있구나. 이것이 물고기의 즐거움이다.\n\n혜자가 말했다. 자네는 물고기가 아닌데 어찌 물고기의 즐거움을 아는가. 장자가 말했다. 자네는 내가 아닌데 어찌 내가 물고기의 즐거움을 모른다는 것을 아는가.\n\n혜자가 말했다. 나는 자네가 아니니 물론 자네를 모르고, 자네도 물고기가 아니니 물고기의 즐거움을 모르는 것은 확실하다. 장자가 말했다. 처음으로 돌아가세. 자네가 어찌 아느냐고 물었을 때, 자네는 이미 내가 안다는 것을 알고서 내게 물은 것이네. 나는 이 다리 위에서 알았다네.",
