    "id": "e49",
    "text": "자사, 자여, 자리, 자래 네 사람이 서로 이야기했다. 누가 삶과 죽음, 있음과 없음이 한 몸임을 알겠는가. 그런 사람과 나는 벗이 되겠다. 네 사람이 서로 보며 웃었다. 마음에 거슬림이 없어 마침내 벗이 되었다.\n\n얼마 뒤 자래가 병들어 죽어 가니, 자리가 문병 와서 말했다. 위대하구나, 조화여. 또 그대를 무엇으로 만들려는가.\n\n자래가 말했다. 큰 덩어리는 내게 형체를 주어 싣고, 삶을 주어 수고롭게 하고, 늙음을 주어 편안하게 하고, 죽음을 주어 쉬게 한다. 그러므로 내 삶을 좋다 하는 것이 곧 내 죽음을 좋다 하는 것이다. 이제 천지를 큰 화로로 삼고 조화를 큰 대장장이로 삼는다면, 어디로 간들 안 될 것이 있겠는가.",
