    "id": "e27",
    "text": "성현의 가르침에는 원래 두 갈래 길이 있다. 사도는 만백성을 가르쳐 저마다 몸을 닦게 했고, 태학에서는 나라의 자제를 가르쳐 저마다 몸을 닦고 백성을 다스리게 했다. 그러므로 군자의 학문은 절반이 몸을 닦는 일이요, 나머지 절반이 백성을 다스리는 일이다.\n\n성인의 시대가 이미 멀어지고 그 말씀도 사라져 그 도가 점점 어두워졌으니, 오늘날 백성을 다스리는 자들은 오직 거두어들이는 데만 급급하고 백성을 먹여 살릴 방도는 알지 못한다.\n\n이 때문에 아랫백성들은 여위고 병들어 줄지어 굶어 죽은 시체가 구덩이를 메우는데, 그들을 다스린다는 자들은 바야흐로 고운 옷과 맛있는 음식으로 저 혼자만 살찌고 있으니, 어찌 슬프지 아니한가.",
