    "id": "e25",
    "text": "무릇 책을 읽을 때는 글자마다 또렷하게 읽어야 한다. 한 글자도 틀리지 말고, 빠뜨리지 말고, 더하지 말고, 뒤바꾸지 말라. 억지로 외우려 들지 말고, 다만 여러 번 되풀이해 읽으면 저절로 입에 붙어 오래도록 잊히지 않는다.\n\n옛사람이 말하기를 \"책을 백 번 읽으면 그 뜻이 저절로 드러난다\" 하였으니, 익숙히 읽으면 남의 설명을 기다리지 않고도 그 뜻을 절로 알게 된다는 말이다.\n\n나는 일찍이 독서에 세 가지 이름(三到)이 있다고 말했다. 마음이 이르고, 눈이 이르고, 입이 이르는 것이다. 마음이 여기에 있지 않으면 눈이 자세히 보지 못하고, 마음과 눈이 하나로 모이지 않으면 그저 되는대로 읊조릴 뿐이라 결코 기억하지 못하며, 기억한들 오래가지 못한다. 셋 중에서는 마음이 이르는 것이 가장 절실하다.",
