    "id": "e5",
    "text": "큰 배움의 도는 밝은 덕을 밝히는 데 있으며, 백성을 새롭게 하는 데 있으며, 지극한 선에 머무는 데 있다.\n\n머무를 곳을 안 뒤에야 뜻이 정해지고, 뜻이 정해진 뒤에야 마음이 고요해지고, 마음이 고요해진 뒤에야 편안해지고, 편안해진 뒤에야 깊이 생각할 수 있고, 깊이 생각한 뒤에야 얻을 수 있다.",
