    "id": "e18",
    "text": "옛사람도 나를 보지 못하고, 나도 옛사람을 보지 못하네.\n옛사람을 보지 못해도 그분들이 가던 길이 앞에 있네.\n가던 길이 앞에 있거늘, 아니 가고 어찌하리.\n\n그때 가던 길을 몇 해나 버려두고\n어디를 다니다가 이제야 돌아왔는고.\n이제야 돌아왔으니 딴 데 마음 두지 않으리.\n\n어리석은 이도 알아서 행하니 그 아니 쉬운가.\n성인도 다 하지 못하시니 그 아니 어려운가.\n쉽거나 어렵거나, 그 사이에 늙는 줄을 모르겠구나.",
