    "id": "e58",
    "text": "안에서든 밖에서든 만나는 것은 곧 죽여라. 부처를 만나면 부처를 죽이고, 조사를 만나면 조사를 죽이고, 나한을 만나면 나한을 죽이고, 부모를 만나면 부모를 죽이고, 친척을 만나면 친척을 죽여라.\n\n그래야 비로소 해탈하여 어떤 것에도 얽매이지 않고 자유로우리라.",
