    "cat": "과학",
    "bm": false,
    "note": "훔볼트는 남미의 밀림과 화산을 직접 누비며, 기후·식물·지질을 하나로 묶어 자연을 '살아 있는 전체'로 보려 했다. 모든 것이 서로 연결되어 있다는 그의 신념이, 만년에 우주 전체를 그려내려 한 이 책 《코스모스》로 이어졌다.",
    "bookTitle": "코스모스",
