    "id": "s19",
    "text": "과학은 사실로 지어진다. 마치 집이 벽돌로 지어지듯. 그러나 사실을 쌓아놓은 것이 과학이 아닌 것은, 벽돌을 쌓아놓은 것이 집이 아닌 것과 같다.\n\n과학자는 자연이라는 거대한 책 앞에 선 독자이다. 이 책은 수학의 언어로 쓰여 있으며, 그 언어를 모르는 자는 한 마디도 이해할 수 없다.",
