    "id": "s26",
    "text": "나는 신이 세계를 창조하실 때 어떤 수학적 질서를 따랐는지 발견하고자 했다. 오랜 세월 씨름한 끝에 나는 마침내 천체들의 운행 속에서 화성이 울려 퍼지고 있음을 보았다.\n\n하늘은 노래한다. 지구는 미와 파를, 그리고 그 사이 반음을 노래한다. 이 화음이야말로 창조주가 세계를 지으실 때 마음에 품었던 조화의 흔적이다. 나는 신께서 자연을 통해 스스로를 드러내신 그 생각을 그분의 생각 그대로 따라가 보았을 뿐이다.",
