    "id": "s37",
    "text": "동물의 심장은 생명의 토대이며, 그 안의 모든 것의 주권자이고, 소우주의 태양이다. 모든 성장이 그것에 의존하며, 모든 힘이 그것으로부터 나온다.\n\n따라서 우리는 필연적으로 이렇게 결론지어야 한다 — 동물의 혈액은 순환하는, 영속적인 운동 속에 놓여 있으며, 심장의 박동이야말로 이 모든 것의 유일한 원인이라고.",
