    "id": "s4",
    "text": "우리는 기쁨으로 환히 빛나는 자연의 얼굴을 바라본다. 먹을 것이 넘쳐난다고 흔히 여긴다. 그러나 우리 주위에서 한가로이 노래하는 저 새들이 대개 벌레와 씨앗을 먹고 살며, 그리하여 끊임없이 생명을 죽이고 있다는 사실은 보지 못하거나 잊고 만다.\n\n살아남을 수 있는 것보다 훨씬 많은 개체가 태어난다는 점을 기억한다면, 아무리 사소한 것이라도 남보다 유리한 점을 지닌 개체가 살아남고 제 종류를 퍼뜨릴 가장 좋은 기회를 얻으리라는 것을 의심할 수 있겠는가. 반대로 조금이라도 해로운 변이는 가차 없이 사라지고 말 것이다.\n\n유리한 변이는 보존되고 해로운 변이는 버려지는 이것을, 나는 자연선택이라 부른다.",
