    "id": "s39",
    "text": "실험과학자로서 그 이름에 합당하려면, 이론가이자 동시에 실천가여야 한다. 과학의 재료인 실험적 사실을 확립하는 기술을 완전히 갖추어야 하며, 자연 현상에 대한 다양한 실험적 탐구를 관통하는 추론을 이끄는 과학적 원리도 명확히 이해해야 한다. 이 둘은 분리할 수 없다 — 머리와 손을. 머리 없는 손은 맹목적인 도구이고, 손 없는 머리는 무력하다.",
