    "id": "s31",
    "text": "인간의 지성을 사로잡고 있는 우상에는 네 가지가 있다.\n\n종족의 우상은 인간이라는 종족 자체에 뿌리박은 편견이다. 동굴의 우상은 각 개인의 성격과 교육과 습관에서 비롯된 편견이다. 시장의 우상은 사람들 사이의 교류와 언어의 부적절한 사용에서 생겨난 편견이다. 극장의 우상은 잘못된 학설과 논증의 규칙에서 들어온 편견이다.\n\n이 우상들을 물리치지 않는 한, 학문에 참된 진보란 있을 수 없다.",
