    "id": "s10",
    "text": "수학에서 어떤 정리가 중요한지 아닌지를 미리 알 수 있는 방법은 없다. 쓸모없어 보이는 것이 나중에 가장 중요한 것으로 밝혀지기도 한다.\n\n수학자는 화가나 시인과 마찬가지로 패턴을 만드는 사람이다. 차이가 있다면 수학의 패턴이 더 오래 남는다는 것이다. 유클리드의 정리가 아이스킬로스의 비극보다 영원에 가깝다는 것은 슬픈 일이 아니다.",
