    "id": "s43",
    "text": "나는 \"기계가 생각할 수 있는가?\"라는 질문을 다루고자 한다. 이 말들을 일상적으로 쓰이는 방식대로 정의한다면, 그 답은 갤럽 여론조사 같은 통계 조사에서 찾아야 한다는 결론을 피하기 어렵다. 그러나 이것은 터무니없다.\n\n그런 정의를 시도하는 대신, 나는 이 질문을 비교적 모호하지 않은 다른 질문으로 바꾸어 놓겠다. 이 새로운 문제는 우리가 '모방 게임'이라 부르는 놀이의 관점에서 설명할 수 있다.",
