    "id": "s50",
    "text": "나는 화성의 궤도를 원으로 맞추려고 8년을 보냈다. 결국 계산은 8분의 오차를 남겼다.\n\n만약 내가 이 8분을 무시해도 좋다고 여겼다면, 나는 이미 세워 둔 가설을 그럭저럭 수정하는 것으로 만족했을 것이다. 그러나 그것을 무시할 수 없었으므로, 이 8분만으로 천문학 전체를 다시 세우는 길이 열렸다.",
    "author": "요하네스 케플러",
