    "note": "티코 브라헤가 남긴 관측 자료는 당대에 가장 정밀했다. 케플러는 그 자료와 자신의 원 궤도 가설 사이에서 8분의 각도 차이를 발견했는데, 이는 육안 관측의 오차 범위보다 작은 값이었다. 그는 그 오차를 버리지 않고 궤도가 타원임을 밝혔다.",
