    "id": "s53",
    "text": "눈이 서로 다른 거리에 초점을 맞추고, 서로 다른 빛의 양을 받아들이며, 구면수차와 색수차를 보정하는 그 비할 데 없는 장치들을 갖추고 있다는 것 — 이런 눈이 자연선택에 의해 형성되었다고 가정하는 것은, 솔직히 고백하건대, 더할 나위 없이 터무니없어 보인다.\n\n그러나 이성은 나에게 이렇게 말한다. 만약 완전한 눈에서 아주 불완전한 눈에 이르는 수많은 단계가 존재했음을 보일 수 있고, 각 단계가 그것을 지닌 생물에게 유용했음을 보일 수 있다면, 자연선택으로 완전한 눈이 만들어졌다고 믿는 데 아무런 어려움도 없다.",
