    "id": "s54",
    "text": "오후 한나절이면 그 땅을 과수원과 목재림과 목초지로 구획하고, 어떤 좋은 참나무나 소나무를 문 앞에 남겨 둘지, 어디서 보아야 쓰러진 나무가 가장 보기 좋을지 정하기에 충분했다. 그러고 나서 나는 그 땅을 그냥 묵혀 두었다.\n\n인간은 '없이도 지낼 수 있는 것들의 수'에 비례하여 부유해진다.",
