    "id": "t31",
    "text": "나는 우리 주님이 어떤 뜻으로 이 말씀을 하셨는지 이해하고자 했다. 그리고 이런 답을 얻었다. 죄는 반드시 있을 수밖에 없다. 그러나 모든 것이 잘 될 것이며, 모든 것이 잘 될 것이며, 모든 방식의 것들이 다 잘 될 것이다.\n\n주님이 이렇게 말씀하신 것은 나를 안심시키기 위해서였지, 죄로 인해 근심하는 나를 방해하려는 것이 아니었다. 사랑이 있는 곳에는, 죄가 있음에도 불구하고 슬픔이 없다.",
