    "id": "t10",
    "text": "여호와는 나의 목자시니 내게 부족함이 없으리로다.\n\n그가 나를 푸른 초장에 누이시며 쉴 만한 물가으로 인도하시는도다. 내 영혼을 소생시키시고 자기 이름을 위하여 의의 길로 인도하시는도다.\n\n내가 사망의 음침한 골짜기로 다닐지라도 해를 두려워하지 않을 것은 주께서 나와 함께 하심이라.",
