    "id": "t6",
    "text": "값싼 은혜는 교회의 치명적 원수이다. 오늘 우리의 싸움은 값싼 은혜에 대항하는 것이다.\n\n값싼 은혜란 창고에 쌓아둔 교리, 아무런 대가도 치르지 않고 베푸는 용서, 회개 없는 세례, 고백 없는 성찬, 개인적 죄의 고백 없는 사면, 제자도 없는 은혜이다.\n\n값비싼 은혜란 밭에 숨겨진 보물이다. 그것을 발견한 사람은 가서 가진 것을 다 팔고 기쁨으로 그 밭을 산다.",
