    "id": "t14",
    "text": "교회는 남을 위해 존재할 때만 교회이다.\n\n교회는 인간 삶의 과제에 참여하는 것에서 시작해야 한다. 지배하는 교회가 아니라 섬기는 교회, 돕는 교회, 봉사하는 교회가 되어야 한다.\n\n그리스도인은 자기만의 종교적 행위에 의해서가 아니라, 세상의 고통에 참여함으로써 그리스도인이 된다.",
