    "text": "하나님이 그대 안에 들어오시려면 그대가 비어 있어야 한다. 그대가 비어 있으면 하나님이 그 빈 곳을 채우신다.\n\n만약 그대가 하나님이 아닌 다른 것으로 가득 차 있다면, 하나님을 위한 자리가 없다. 그러므로 비워라. 모든 피조물과 모든 시간과 모든 형상을 비워라. 그러면 하나님이 오실 것이다.",
