    "id": "t3",
    "text": "마음에는 이성이 알지 못하는 이유가 있다.\n\n우리는 진리를 이성에 의해서만이 아니라 마음에 의해서도 인식한다. 첫 번째 원리들을 아는 것은 바로 이 마음이며, 이성의 추론은 여기에 관여하지 않는다.\n\n이성이 마음에게 네가 틀렸다고 요구하는 것은 헛된 일이다. 마찬가지로 마음이 이성에게 네가 불필요하다고 말하는 것도 우스운 일이다.",
