    "bm": false,
    "note": "『프로슬로기온』의 원래 제목은 '이해를 추구하는 믿음(fides quaerens intellectum)'이었다. 이 문장으로 1장이 끝나고, 곧이어 2장에서 그 유명한 신 존재 증명(존재론적 논증)이 전개된다.",
