    "id": "e55",
    "text": "물과 뭍에 피는 꽃 가운데 사랑스러운 것이 매우 많다. 진나라 도연명은 유독 국화를 사랑했고, 당나라 이래로 세상 사람들은 모란을 몹시 사랑했다.\n\n나는 홀로 연꽃을 사랑한다. 진흙에서 나왔으되 물들지 않고, 맑은 물결에 씻겼으되 요염하지 않으며, 속은 비고 겉은 곧아 덩굴지지도 가지 치지도 않는다. 향기는 멀수록 더욱 맑고, 우뚝하고 깨끗하게 서 있어, 멀리서 바라볼 수는 있어도 함부로 가지고 놀 수는 없다.\n\n내가 생각하기에 국화는 꽃 중의 은둔자요, 모란은 꽃 중의 부귀한 자요, 연꽃은 꽃 중의 군자다. 아, 국화를 사랑하는 이는 도연명 이후로 들은 바가 드물다. 연꽃을 사랑하는 이는 나와 같은 이가 몇이나 될까. 모란을 사랑하는 이야 마땅히 많으리라.",
    "author": "주돈이",
    "source": "애련설",
    "cat": "동양고전",
    "bm": false,
    "note": "주돈이는 성리학의 문을 연 북송의 학자로, 주희의 스승 계보에 놓인다. 글 전체가 200자 남짓한 짧은 산문이지만, 진흙에서 나되 물들지 않는 연꽃이라는 이 비유는 이후 동아시아에서 군자의 표상으로 굳어졌다.",
    "bookTitle": "애련설",
