    "id": "e56",
    "text": "석상 화상이 말했다. \"백 척 장대 끝에서 어떻게 한 걸음 더 나아가겠는가?\"\n\n또 옛 어른이 말했다. \"백 척 장대 끝에 앉아 있는 사람은 비록 경지에 들었다 하나 아직 참되지 못하다. 백 척 장대 끝에서 모름지기 한 걸음 더 내디뎌야, 시방세계에 온몸을 드러내리라.\"\n\n무문이 이르되, 한 걸음 나아가 몸을 뒤집을 수 있다면 어느 곳에선들 존귀하다 일컬어지지 않겠는가. 그러나 그렇다 해도 말해보라. 백 척 장대 끝에서 어떻게 한 걸음 더 나아갈 것인가?",
    "author": "무문혜개",
    "source": "무문관, 제46칙 간두진보",
    "cat": "동양고전",
    "bm": false,
    "note": "'백척간두 진일보(百尺竿頭進一步)'라는 말이 여기서 나왔다. 이미 다다른 자리에 머무르는 것을 경계하는 공안으로, 무문은 답을 주는 대신 같은 물음을 되돌려 준다.",
    "bookTitle": "무문관",
    "isbn": "",
    "publisher": "",
    "translator": "",
    "kyoboLink": "https://bitl.bz/api@eoFRRGUt",
