    "id": "e57",
    "text": "서자가 물었다. 공자께서 자주 물을 일컬어 \"물이여, 물이여\" 하셨는데, 물에서 무엇을 취하신 것입니까.\n\n맹자가 말했다. 근원이 있는 샘물은 콸콸 솟아 밤낮으로 그치지 않고, 웅덩이를 채운 뒤에야 나아가 마침내 사해에 이른다. 근본이 있는 것이 이와 같으니, 바로 이것을 취하신 것이다.\n\n만일 근본이 없다면, 칠팔월 사이에 빗물이 모여 도랑과 개천이 모두 가득 차지만, 그것이 마르는 것은 서서 기다릴 수 있을 만큼 잠깐이다. 그러므로 명성이 실제보다 지나친 것을 군자는 부끄러워한다.",
    "author": "맹자",
    "source": "맹자, 이루 하편 18장",
    "cat": "동양고전",
    "bm": false,
    "note": "공자가 강가에서 \"흘러가는 것이 이와 같구나\" 하고 탄식한 대목(논어 자한편)을 두고, 제자 서자가 그 뜻을 물은 것이다. '영과이후진(盈科而後進)', 곧 웅덩이를 채운 뒤에야 나아간다는 말이 여기서 나왔다.",
    "bookTitle": "맹자",
