    "note": "20세기 초 영국에서 신앙이 비합리라는 공격을 받던 시기에 쓰인 책이다. 체스터튼은 광기를 이성의 결핍이 아니라, 이성만 남은 상태로 본다.",
    "bookTitle": "정통",
