    "id": "t54",
    "text": "레오 형제여, 적어 두게. 무엇이 참된 기쁨인지.\n\n사신이 와서 파리의 모든 학자들이 우리 수도회에 들어왔다고 알린다 해도, 그것은 참된 기쁨이 아니네. 죽은 이를 살리는 능력을 내가 가졌다 해도, 그것 역시 참된 기쁨이 아니네.\n\n참된 기쁨은 이것이네. 내가 한밤중에 진흙투성이가 되어 추위에 떨며 돌아와 문을 두드릴 때, 문지기가 나와 \"너는 누구냐\" 묻고, 내가 \"프란치스코 형제요\" 하면, 그가 \"꺼져라, 이 무식한 놈아. 우리는 많으니 너는 필요 없다\" 하며 문을 열어 주지 않을 때 — 그때 내가 참을성을 잃지 않고 마음이 흔들리지 않는다면, 바로 그것이 참된 기쁨이라네.",
    "author": "아시시의 프란치스코",
