    "id": "l116",
    "text": "\"나도 예전에 소설을 한 편 썼답니다.\"\n\n\"정말이세요, 프리즘 선생님? 정말 대단하시네요! 그런데 행복하게 끝나지는 않았기를 바라요. 저는 행복하게 끝나는 소설은 안 좋아하거든요. 너무 우울해지니까요.\"\n\n\"선한 사람은 행복하게, 나쁜 사람은 불행하게 끝났답니다. 그것이 바로 소설이라는 것의 의미예요.\"\n\n\"그런 것 같긴 한데… 정말 불공평해 보여요.\"",
    "author": "오스카 와일드",
    "source": "진지함의 중요성, 2막",
    "cat": "문학",
    "bm": false,
    "note": "세실리가 가정교사 프리즘에게 그녀가 젊은 시절 쓴 소설에 대해 묻는 대목이다. 행복한 결말이 우울하게 만든다는 세실리의 말은 이유가 설명되지 않은 채 던져진다. 소설이 늘 선인을 행복하게, 악인을 불행하게 끝맺는다는 프리즘의 공식 앞에서, 세실리는 그것이 현실에는 없는 억지 정산임을 이미 알고 있다.",
    "bookTitle": "진지함의 중요성",
