    "note": "소설 본문이 시작되기 전, 와일드가 따로 붙인 서문의 마지막 대목이다. 이 소설은 출간 당시 부도덕하다는 비난을 받았는데, 그는 애초에 책에 도덕을 묻는 질문 자체가 틀렸다고 선언하며 시작한다.",
    "bookTitle": "도리언 그레이의 초상",
