    "text": "유토피아가 빠진 세계지도는 쳐다볼 가치도 없다. 인류가 늘 도착하려 하는 그 하나의 나라를 빼놓았으니까. 그리고 인류가 그곳에 도착하면, 밖을 내다보다가 더 나은 나라를 발견하고는 다시 돛을 올린다. 진보란 유토피아들을 실현해 나가는 것이다.",
