    "id": "p92",
    "text": "사람들은 대개 건강하지 못하고 과장된 이타심으로 자기 삶을 망친다 — 실은 그렇게 될 수밖에 없이 내몰린다. 그들은 끔찍한 빈곤과 추함과 굶주림에 둘러싸여 있다. 이 모든 것에 마음이 크게 움직이는 것은 당연하다.\n\n그러나 인간의 감정은 지성보다 훨씬 빨리 흔들린다. 고통에 공감하기는 쉬워도 사유에 공감하기는 훨씬 어렵다. 그래서 사람들은 훌륭하지만 잘못된 의도로, 아주 진지하고 감상적으로 눈에 보이는 악을 고치는 일에 나선다. 그러나 그들의 처방은 병을 고치지 못한다. 그저 병을 연장할 뿐이다. 사실 그 처방 자체가 병의 일부다.",
