    "id": "s57",
    "text": "해석기관은 대수적 패턴을 짜 나간다, 마치 자카드 방직기가 꽃과 잎사귀 무늬를 짜듯이.\n\n상상력은 발견하는 능력이다. 그것은 우리를 둘러싼 보이지 않는 세계, 곧 과학의 세계를 꿰뚫고 들어간다.\n\n해석기관은 무언가를 스스로 창조해 낸다고 주장할 수 없다. 그것은 우리가 수행하도록 명령할 줄 아는 것이라면 무엇이든 해낼 수 있을 뿐이다.",
