    "id": "l125",
    "text": "흔하다는 사실 자체에 깃든 비극은, 아직 인류의 무딘 감정 속으로 스며들지 못했다. 어쩌면 우리의 몸이 그것을 많이 감당하지 못하기 때문일지도 모른다.\n\n만일 우리가 모든 평범한 삶을 예리하게 보고 느낄 수 있다면, 그것은 풀이 자라는 소리와 다람쥐의 심장이 뛰는 소리를 듣는 것과 같으리라. 그리고 우리는 침묵의 저편에 놓인 그 굉음에 그만 숨이 끊어지고 말 것이다.",
