    "id": "p94",
    "text": "젊은이들이 자신이 얼마나 빨리 한낱 걸어 다니는 습관 덩어리가 되고 마는지를 깨닫기만 한다면, 아직 말랑말랑한 시기에 자기 행동을 더 조심할 것이다.\n\n우리는 스스로 자기 운명을 짜고 있으며, 좋은 쪽으로든 나쁜 쪽으로든 그것은 결코 되돌릴 수 없다. 미덕이든 악덕이든, 아주 작은 한 번의 붓질조차 그 나름의 옅은 흉터를 남긴다.",
