    "id": "t56",
    "text": "이 세상의 모든 완전함에는 얼마간의 불완전함이 섞여 있고, 우리의 앎에는 어떤 어둠이 깃들어 있다. 겸손하게 자기를 아는 것이 학문을 깊이 파고드는 것보다 하느님께 이르는 더 확실한 길이다.\n\n배움을 탓하는 것도, 그 자체로 선하며 하느님이 정하신 지식을 탓하는 것도 아니다. 다만 깨끗한 양심과 덕된 삶이 언제나 그보다 앞서야 한다. 많은 이들이 잘 살기보다 많이 알기를 애쓰다가 길을 잃고, 열매를 거의 맺지 못한다.\n\n그러니 심판의 날이 오면, 우리가 무엇을 읽었는지가 아니라 무엇을 행했는지를 물으실 것이다. 얼마나 말을 잘했는지가 아니라 얼마나 경건하게 살았는지를.",
