    "note": "블레이크에게 지옥은 죄인을 벌하는 곳이 아니라, 에너지와 욕망과 육체 — 곧 살아 있는 힘이 솟는 곳이다. 그는 이성과 절제를 앞세우는 제도 종교의 '천국'이 오히려 생명을 억누른다고 보았고, '대립 없이는 전진도 없다'며 선과 악을 서로를 낳는 짝으로 여겼다. '지옥의 격언'은 바로 그 억눌린 편에 서서, 천국의 도덕이 죄라 부른 것들 속에서 지혜를 길어 올린다.",
