    "id": "p95",
    "text": "당신 말이 다 옳습니다. 제가 얼마나 빠르게 번영에 올랐는지 부정할 수 없지요. 하지만 바로 그 기억이 지금 저를 슬픔으로 태웁니다. 온갖 역경 가운데 가장 비참한 종류의 불행은, 한때 행복했었다는 사실이니까요.",
