    "text": "두 번째 기회, 그것은 착각이다. 애초에 단 한 번뿐이었다. 우리는 어둠 속에서 일한다 — 할 수 있는 것을 하고, 가진 것을 내어준다. 우리의 의심이 곧 우리의 열정이며, 그 열정이 곧 우리의 일이다. 나머지는 예술의 광기다.",
