    "text": "우리에게 날개가 돋고 다른 호흡기가 생겨 무한한 공간을 가로지른다 해도 소용없으리라. 같은 감각을 지닌 채 화성이나 금성에 간들, 거기서 보는 것마다 지구의 사물과 똑같은 모습으로 뒤덮어 볼 테니까. 유일하게 참된 여행, 젊음을 되찾는 유일한 샘은, 낯선 땅을 찾는 것이 아니라 다른 눈을 갖는 것이다. 다른 사람의 눈으로, 백 사람의 눈으로 우주를 보는 것 — 그들 각자가 보는 백 개의 우주를, 그들 각자인 백 개의 우주를 보는 것이다.",
