    "text": "지금 생각하는 것을 오늘의 단단한 말로 하라. 내일은 내일 생각하는 것을 다시 단단한 말로 하라 — 그것이 오늘 한 말과 온통 모순될지라도. \"하지만 그러면 반드시 오해받을 것이다.\" 오해받는 것이 그토록 나쁜 일인가? 피타고라스도 오해받았고, 소크라테스도, 예수도, 코페르니쿠스도, 갈릴레오도, 뉴턴도 그러했다.",
