    "id": "p100",
    "text": "일리아스의 진정한 주인공, 진정한 주제, 그 중심은 힘이다.\n\n힘이란 그것에 굴복한 자를 사물로 만드는 것이다. 끝까지 행사될 때 힘은 사람을 가장 문자 그대로의 의미에서 사물로 만든다. 시체로 만들기 때문이다. 조금 전까지 누군가가 있었는데, 한순간 뒤에는 아무도 없다.",
