    "id": "l144",
    "text": "\"제가 신문을 탓하는 건, 날마다 하찮은 것들에 주의를 기울이게 만든다는 점입니다. 정작 본질적인 것이 담긴 책은 평생 서너 번밖에 읽지 않으면서 말이죠. 어차피 아침마다 조바심치며 신문 띠지를 뜯을 거라면, 차라리 바꿔야 해요. 신문에는, 글쎄요, 파스칼의…… 『팡세』 같은 걸 싣고요!\n\n그리고 그리스 왕비가 칸에 갔다거나 레옹 대공비가 가장무도회를 열었다는 소식은, 십 년에 한 번 펼칠까 말까 한 금박 장정본에서나 읽는 겁니다. 그래야 제대로 균형이 맞겠죠.\"",
