    "note": "주인공이 샹젤리제 공원에서 함께 놀던 첫사랑 질베르트를 한동안 만나지 못하던 때의 이야기. 사랑하는 사람 앞에서 우리는 몸짓 하나, 표정 하나를 따라가며 신호를 읽어 내느라 바쁘다. 정작 무심히 지나친 얼굴만이 흔들림 없이 한 장의 사진으로 남는다. 얼굴이 떠오르지 않자 주인공은 사랑이 식은 게 아닐까 의심하지만, 기억하지 못하는 건 사랑이 식어서가 아니다. 오히려 그 반대다.",
