    "text": "\"가장 큰 어리석음은 자기가 느끼지 못하는 감정을 우습게 여기거나 비난하는 거라네. 나는 밤을 좋아하는데 자네는 밤이 무섭다고 하지. 나는 장미 향을 좋아하는데, 내 친구 하나는 그 향만 맡으면 열이 난다네. 그렇다고 내가 그 친구를 나보다 못하다고 여기겠나? 나는 모든 걸 이해하려 애쓰고, 무엇도 비난하지 않으려 조심하네.\n\n세상이 이해하지 못할 일로도 사람은 몹시 괴로울 수 있다는 걸 나도 아네. 그래도 적어도 자네는 애정을 할머니께, 현명한 곳에 두었지. 그건 정당한 애정, 그러니까 보답받는 애정이야. 그렇게 말할 수 없는 애정이 얼마나 많은지.\"",
