    "text": "라 베르마의 공연을 처음 보고 아무 즐거움도 느끼지 못한 건 너무 큰 기대 때문이라고 생각했다. 그러나 이유는 더 깊은 데 있었는지도 모른다. 개성이 강한 사람이나 작품이 주는 인상은 저마다 고유하다. 우리는 '아름다움', '웅장함', '비장함' 같은 관념을 챙겨 가지만, 정작 잔뜩 집중한 우리 앞에 버티고 선 것은 어떤 관념에도 들어맞지 않는 형태다. 우리는 속으로 묻는다. '이게 아름다운 건가?' 대답으로 돌아오는 건 그 배우의 낯선 목소리와 억양뿐이다. 그래서 정말 아름다운 작품일수록 진지하게 들을 때 우리를 가장 실망시키게 마련이다. 우리 관념의 목록에는 개별적인 인상에 들어맞는 것이 하나도 없으니까.",
