    "text": "혁명을 동경한 적도 없었고, 사랑조차 알지 못했다. 지금까지 세상의 어른들은 혁명과 사랑, 이 두 가지를 가장 어리석고 꺼림칙한 것이라 우리에게 가르쳤고, 전쟁 전에도 전쟁 중에도 우리는 그렇게 믿었다. 그런데 패전 뒤 우리는 세상의 어른들을 믿지 않게 되었고, 무엇이든 그 사람들이 하는 말의 반대편에 진짜 살아갈 길이 있는 것만 같았다. 혁명도 사랑도 실은 이 세상에서 가장 좋고 맛있는 것이라서, 너무 좋은 것이라서, 어른들이 심술궂게 우리에게 덜 익은 포도라고 거짓말을 한 게 틀림없다고 생각하게 되었다.\n\n나는 확신하고 싶다. 인간은 사랑과 혁명을 위해 태어난 것이다.",
