    "id": "s60",
    "text": "우리 가운데 전차를 타는 사람은, 전문 물리학자가 아닌 한, 그것이 어떻게 스스로 움직이는지 전혀 알지 못한다.\n\n그러므로 점점 커지는 지성화와 합리화란, 우리가 처한 삶의 조건을 더 잘 알게 되었다는 뜻이 아니다. 그것은 다른 뜻이다. 원하기만 하면 언제든 알아낼 수 있다는 앎, 혹은 그렇다는 믿음이다. 곧 거기에 끼어드는 신비롭고 헤아릴 수 없는 힘 따위는 원리상 존재하지 않으며, 오히려 모든 것을 원리상 계산을 통해 지배할 수 있다는 것이다.\n\n그리고 그것이 곧 세계의 탈주술화를 뜻한다.",
