    "id": "t57",
    "text": "기독교 신경의 모든 조항이 지적인 난점에 둘러싸여 있다는 것을 나는 결코 부인하지 않는다. 그리고 나 자신이 그 난점들에 답할 수 없다는 것도 단순한 사실이다. 많은 이들이 신앙의 난점에 예민하다. 나 역시 누구 못지않게 예민하다. 그러나 그 난점들을 아무리 날카롭게 느끼고 아무리 많이 쌓아 올린다 해도, 그것과 거기 딸린 교리를 의심하는 일 사이에서 나는 어떤 연결도 찾을 수 없었다.\n\n만 개의 난점이 하나의 의심을 만들지는 않는다. 내가 이해하는 한, 난점과 의심은 서로 잴 수 없는 것이다.",
