    "id": "s63",
    "text": "큰 배의 갑판 아래 선실에 친구와 함께 들어가 문을 닫아 보라. 파리와 나비 몇 마리, 물고기가 든 어항도 함께 두라. 배가 멈춰 있을 때, 벌레들이 선실 어느 쪽으로나 같은 빠르기로 날고 물고기가 아무 방향으로나 헤엄치는 것을 잘 보아 두라.\n\n그런 다음 배를 원하는 만큼 빠르게 몰되, 흔들림 없이 한결같이 가게 하라. 나비와 파리는 여전히 아무 쪽으로나 날아다닐 것이고, 배를 쫓아가느라 지쳐 뒤쪽에 몰려드는 일은 결코 없을 것이다. 그 무엇으로도 배가 가고 있는지 서 있는지 알 수 없을 것이다.",
