    "note": "17세기 파리 가르멜 수도원의 평수사 로렌스 형제의 말로, 그를 찾아온 보포르 신부가 기록해 전했다. 그는 원래 부엌일을 몹시 싫어했지만 15년 가까이 수도원 부엌을 맡았다. 그에게 신앙은 일상에서 물러나 따로 찾아가는 자리가 아니라, 하기 싫은 일까지 품은 하루 전체를 살아 내는 방식이었다.",
