    "cat": "문학",
    "bm": false,
    "note": "소설 초반, 추운 밤 도버로 가는 우편 마차 안. 외투를 귀까지 여민 승객들은 좁은 마차에 함께 있으면서도 서로가 누구인지 모른 채 말 한마디 없이 앉아 있다. 화자는 이 낯선 동승자들에게서 출발해, 가장 가까운 사람조차 끝내 알 수 없다는 생각에 이른다. 이 비밀은 쓸쓸함이기도 하지만, 뒤집어 보면 한 사람 한 사람이 끝내 다 읽히지 않을 만큼 깊다는 뜻이기도 하다.",
