    "id": "l152",
    "text": "\"베드로는 밖으로 나가 슬피 울었다.\" 학생은 한숨을 쉬었다. 모닥불 곁의 늙은 과부가 미소를 머금은 채 갑자기 흐느꼈다. 굵은 눈물이 뺨을 타고 흘렀고, 그녀는 부끄러운 듯 소매로 얼굴을 가렸다.\n\n노파가 운 것은 그가 이야기를 잘해서가 아니었다. 베드로의 일이 그녀에게 남의 일이 아니었기 때문이다. 문득 그의 마음속에서 기쁨이 일렁였다. 그는 열아홉 세기 전과 지금을 잇는 사슬의 양 끝을 방금 본 것만 같았다. 한쪽 끝을 건드리자, 다른 쪽 끝이 떨렸다.",
