    "note": "353년 늦봄, 왕희지가 벗들과 물가에서 술잔을 띄우며 시를 짓던 날, 그 시들을 엮은 문집에 붙인 서문. 그는 훗날 '서예의 성인'이라 불린 사람으로, 그가 직접 붓으로 쓴 이 글은 지금도 천하제일의 글씨로 꼽힌다. 옛사람의 글을 읽으며 탄식하던 그는, 이 글에서 스스로 옛사람이 되어 뒷날의 독자에게 말을 건다. 1,700년 가까이 지나 그 '뒷날'에 도착한 것이 지금 이 글을 읽는 우리다.",
